  "smartspec_media_studio_production_shot_auto_image_qa_v1";
const DENSE_PRODUCTION_SHOT_NODE_ID_PATTERN =
  /^shot-\d+-(script|image-prompt|image-output|video-prompt|video-output|audio-prompt|audio-output|qa)$/;

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function stringArrayFromUnknown(value: unknown): string[] {
  if (Array.isArray(value))
    return value.map(item => String(item ?? "").trim()).filter(Boolean);
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return [];
    if (trimmed.startsWith("[")) {
      try {
        const parsed = JSON.parse(trimmed);
        if (Array.isArray(parsed))
          return parsed.map(item => String(item ?? "").trim()).filter(Boolean);
      } catch {
        return [trimmed];
      }
    }
    return trimmed
      .split(/[,\n|]+/g)
      .map(item => item.trim())
      .filter(Boolean);
  }
  return [];
}

function compactMarketplaceAutoReviewText(value: unknown): string {
  return typeof value === "string" ? value.trim() : "";
}

function marketplaceAutoReviewRefs(value: unknown): string[] {
  return Array.isArray(value)
    ? value.map(item => String(item ?? "").trim()).filter(Boolean)
    : [];
}

