const DECORATIVE_STORY_CONCEPT_SYMBOL_PATTERN =
  /[\p{Extended_Pictographic}\uFE0F\u20E3]/gu;
const PRODUCTION_STORY_CONCEPT_DETAILS_MAX_CHARS = 520;
const PRODUCTION_STORY_CONCEPT_DETAILS_PRODUCT_MAX_CHARS = 120;
