function normalizeStoryConceptPromptText(value: unknown): string {
  return String(value ?? "")
    .replace(DECORATIVE_STORY_CONCEPT_SYMBOL_PATTERN, "")
    .replace(/^[\s>*•·▪▫◦‣⁃\-=+|]+/gm, "")
    .replace(/[ \t]+/g, " ")
    .replace(/\s*\n\s*/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function clampStoryConceptText(value: unknown, maxChars: number): string {
  const text = normalizeStoryConceptPromptText(value);
  if (text.length <= maxChars) return text;
  const sliced = text.slice(0, maxChars + 1);
  const boundaryIndexes = [
    sliced.lastIndexOf("."),
    sliced.lastIndexOf("!"),
    sliced.lastIndexOf("?"),
    sliced.lastIndexOf(","),
    sliced.lastIndexOf("/"),
    sliced.lastIndexOf(" "),
  ];
  const boundary = Math.max(...boundaryIndexes);
  return sliced
    .slice(0, boundary >= Math.floor(maxChars * 0.65) ? boundary : maxChars)
    .trim();
}

function inferStoryConceptLocaleFromText(values: unknown[]): "th" | "en" {
  return values.some(value => /[\u0E00-\u0E7F]/.test(String(value ?? "")))
    ? "th"
    : "en";
}

function joinCompactStoryConceptParts(
  parts: string[],
  maxChars = PRODUCTION_STORY_CONCEPT_DETAILS_MAX_CHARS
): string {
  return parts.reduce((output, part) => {
    const text = normalizeStoryConceptPromptText(part);
    if (!text) return output;
    const candidate = output ? `${output} ${text}` : text;
    if (candidate.length <= maxChars) return candidate;
    return output || clampStoryConceptText(text, maxChars);
  }, "");
}

function escapeStoryConceptRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function extractStoryConceptDetailSegment(
  text: string,
  labels: string[]
): string {
  const source = normalizeStoryConceptPromptText(text);
  if (!source) return "";
  const stopLabels = [
    "ชื่อสินค้า",
    "สินค้า",
    "รายละเอียดสินค้าที่สรุปมาแล้วคือ",
    "รายละเอียดย่อ",
    "แนวคิด",
    "กลุ่มเป้าหมายคือ",
    "กลุ่มเป้าหมาย",
    "ปัญหาที่ต้องหยิบมาเล่าคือ",
    "ปัญหา",
    "จุดขายหลักคือ",
    "จุดขาย",
    "เปิดด้วยประโยค hook ว่า",
    "Hook",
    "จากนั้นพาไปเห็นการใช้งานจริงว่า",
    "บริบทใช้จริง",
    "Product name",
    "Product",
    "Summarized product details",
    "Brief details",
    "Concept",
    "Target audience",
    "Audience",
    "Problem",
    "Selling points",
    "Opening hook",
    "Use case",
    "Real use case",
  ].filter(
    label =>
      !labels.some(
        activeLabel => activeLabel.toLowerCase() === label.toLowerCase()
      )
  );
  const labelPattern = labels.map(escapeStoryConceptRegExp).join("|");
  const stopPattern = stopLabels.map(escapeStoryConceptRegExp).join("|");
  const match = source.match(
    new RegExp(
      `(?:${labelPattern})\\s*[:：]?\\s*(.+?)(?=\\s+(?:${stopPattern})\\s*[:：]?|$)`,
      "i"
    )
  );
  return normalizeStoryConceptPromptText(match?.[1] ?? "");
}

function isTemplateStoryConceptDetailsText(value: unknown): boolean {
  const text = normalizeStoryConceptPromptText(value);
  if (!text) return false;
  const templateLabels = [
    "สินค้า:",
    "รายละเอียดย่อ:",
    "แนวคิด:",
    "กลุ่มเป้าหมาย:",
    "ปัญหา:",
    "จุดขาย:",
    "Product name:",
    "Product:",
    "Brief details:",
    "Summarized product details:",
    "Concept:",
    "Audience:",
    "Problem:",
    "Selling points:",
  ];
  const labelCount = templateLabels.filter(label =>
    text.toLowerCase().includes(label.toLowerCase())
  ).length;
  return (
    labelCount >= 3 ||
    /จุดเด่นหลักของ|รีวิวสินค้า|Main value of|marketplace description/i.test(
      text
    )
  );
}

function inferStoryConceptDimension(
  concept: CompactProductionStoryConcept
): NonNullable<ProductionStoryConceptOption["storyDimension"]> {
  if (concept.storyDimension) return concept.storyDimension;
  const marker = normalizeStoryConceptPromptText(
    [concept.storyOptionId, concept.title, concept.angle]
      .filter(Boolean)
      .join(" ")
  ).toLowerCase();
  if (/objection|proof|trust|ข้อกังวล|ความมั่นใจ|หลักฐาน/.test(marker))
    return "objection_trust";
  if (/quick|demo|เดโม|รวมประโยชน์/.test(marker)) return "quick_demo";
  if (/use.case|real use|สถานการณ์|mini story|ใช้งานจริง/.test(marker))
    return "use_case_moment";
  return "problem_solution";
}

function compactProductBrand(value: string): string {
  return (
    normalizeStoryConceptPromptText(value).match(
      /^([A-Za-z][A-Za-z0-9-]*)\b/
    )?.[1] ?? ""
  );
}

function compactProductReference(input: {
  productName: string;
  productDetails: string;
  locale: "th" | "en";
}): string {
  const { productName, productDetails, locale } = input;
  const source = `${productName} ${productDetails}`.toLowerCase();
  const brand = compactProductBrand(productName);
  const brandPrefix = brand ? `${brand} ` : "";
  if (
    /โต๊ะ|ชั้นวาง|ข้างเตียง|นอร์ดิก|bedside|side table|shelf|nightstand/i.test(
      source
    )
  ) {
    return locale === "th"
      ? `${brandPrefix}โต๊ะ/ชั้นวางข้างเตียงขนาดเล็ก`
      : `${brandPrefix}compact bedside table or shelf`;
  }
  if (
    /เก้าอี้.*เด็ก|กินข้าวเด็ก|โต๊ะกินข้าวเด็ก|baby|high chair|kids dining/i.test(
      source
    )
  ) {
    return locale === "th"
      ? `${brandPrefix}เก้าอี้ทานข้าวเด็ก`
      : `${brandPrefix}kids dining chair`;
  }
  return clampStoryConceptText(
    productName ||
      productDetails ||
      (locale === "th" ? "สินค้านี้" : "this product"),
    PRODUCTION_STORY_CONCEPT_DETAILS_PART_MAX_CHARS
  );
}

function isLowValueStorySellingPoint(
  value: string,
  productName: string,
  productDetails: string
): boolean {
  const text = normalizeStoryConceptPromptText(value);
  if (!text) return true;
  if (
    /จุดเด่นหลักของ|รีวิวสินค้า|รายละเอียดสินค้า|Main value of|Relevant to|product details/i.test(
      text
    )
  )
    return true;
  const normalized = normalizePlanningText(text);
  const product = normalizePlanningText(productName);
  const details = normalizePlanningText(productDetails);
  return Boolean(
    (product &&
      normalized.includes(product.slice(0, 40)) &&
      normalized.length > 55) ||
    (details && normalized === details)
  );
}

