function buildInfographicPromptFromStoryboardSkillOutput(
  parsed: unknown,
  fallbackPrompt: string
): string {
  const record =
    parsed && typeof parsed === "object"
      ? (parsed as Record<string, unknown>)
      : {};
  const mainPrompt = firstNonEmpty(
    readStringValue(record, "main_prompt"),
    readStringValue(record, "prompt"),
    fallbackPrompt
  );
  const negativePrompt = readStringValue(record, "negative_prompt");
  const summary = readStringValue(record, "thai_summary");
  const qaChecklist = Array.isArray(record.qa_checklist)
    ? record.qa_checklist.map(String).filter(Boolean).slice(0, 8)
    : [];
  const handoffNotes = Array.isArray(record.handoff_notes)
    ? record.handoff_notes.map(String).filter(Boolean).slice(0, 6)
    : [];
  const visualSourceOfTruthNotes = Array.isArray(
    record.visual_source_of_truth_notes
  )
    ? record.visual_source_of_truth_notes
        .map(String)
        .filter(Boolean)
        .slice(0, 6)
    : [];
  const productFidelityLock =
    record.product_fidelity_lock &&
    typeof record.product_fidelity_lock === "object" &&
    !Array.isArray(record.product_fidelity_lock)
      ? (record.product_fidelity_lock as Record<string, unknown>)
      : null;
  const productFidelityPreserve = Array.isArray(productFidelityLock?.preserve)
    ? productFidelityLock.preserve.map(String).filter(Boolean).slice(0, 8)
    : [];
  const productFidelityForbidden = Array.isArray(
    productFidelityLock?.forbidden_changes
  )
    ? productFidelityLock.forbidden_changes
        .map(String)
        .filter(Boolean)
        .slice(0, 8)
    : [];
  return [
    "PRODUCT REFERENCE LOCK: Use attached product reference image(s) as the visual source of truth for the product. Preserve the exact visible product identity from the images; do not replace it with a similar generic product.",
    "TRADEMARK / LOGO SAFETY LOCK: Do not invent, stylize, redraw, or add any brand mark, trademark, certification badge, marketplace badge, shop logo, app logo, or platform logo. Do not copy logos from source/reference images into the infographic. The only exception is a logo physically printed on the product/package itself; preserve it only as an incidental product detail, never as a standalone header or decoration.",
    "PRICE / PROMOTION SAFETY LOCK: Do not include prices, discount percentages, vouchers, promo badges, free-shipping claims, campaign conditions, countdown deals, installment terms, sale banners, or limited-time offers. Omit these even if they appear in marketplace screenshots or metadata because they change frequently.",
    productFidelityPreserve.length
      ? `Preserve from product reference images: ${productFidelityPreserve.join("; ")}`
      : "",
    productFidelityForbidden.length
      ? `Do not alter/substitute: ${productFidelityForbidden.join("; ")}`
      : "",
    mainPrompt,
    summary ? `Storyboard planner summary: ${summary}` : "",
    visualSourceOfTruthNotes.length
      ? `Visual source-of-truth notes: ${visualSourceOfTruthNotes.join("; ")}`
      : "",
    negativePrompt ? `Negative prompt / avoid: ${negativePrompt}` : "",
    qaChecklist.length ? `QA checklist: ${qaChecklist.join("; ")}` : "",
    handoffNotes.length ? `Handoff notes: ${handoffNotes.join("; ")}` : "",
    "Use every attached reference image according to its role. Product images control product visuals; scene/style images control only environment, mood, lighting, and layout around the product.",
    "Before finalizing, verify there is no unauthorized logo/trademark/badge and no price/promotion/offer text in the image.",
  ]
    .filter(Boolean)
    .join("\n\n");
}

function getMediaModelRecordId(model: any): string {
  return String(model?.modelId ?? model?.id ?? "").trim();
}

function getMediaModelGenerateType(model: any): string {
  const config = parseMediaModelConfig(model?.configJson);
  return String(config?.generateType ?? config?.generate_type ?? "")
    .trim()
    .toLowerCase();
}

function isReferencePreservingImageModel(model: any): boolean {
  const generateType = getMediaModelGenerateType(model);
  if (!generateType) return false;
  const supportsImageReferences = getModelReferenceInputSupport({
    id: getMediaModelRecordId(model),
    name: String(model?.name ?? getMediaModelRecordId(model)),
    provider: model?.provider ? String(model.provider) : undefined,
    configJson: model?.configJson,
  }).imageUrls;
  if (!supportsImageReferences) return false;
  if (/^(text-to-image|text2image|txt2img|t2i)$/.test(generateType))
    return false;
  return /(image-to-image|image2image|img2img|image-edit|edit|inpaint|reference-to-image|reference-image)/.test(
    generateType
  );
}

function resolveProductionInfographicImageModel(params: {
  preferredModelId?: string;
  imageModels: any[];
  hasProductReferenceImages: boolean;
}): { modelId?: string; model?: any; switchedForProductReference: boolean } {
  const preferredModelId = String(params.preferredModelId ?? "").trim();
  const preferredModel = params.imageModels.find(
    model => getMediaModelRecordId(model) === preferredModelId
  );
  if (preferredModelId) {
    return {
      modelId: preferredModelId || getMediaModelRecordId(preferredModel),
      model: preferredModel,
      switchedForProductReference: false,
    };
  }
  if (!params.hasProductReferenceImages) {
    return {
      modelId: undefined,
      model: undefined,
      switchedForProductReference: false,
    };
  }
  const referencePreservingModel = params.imageModels.find(model =>
    isReferencePreservingImageModel(model)
  );
  if (referencePreservingModel) {
    return {
      modelId: getMediaModelRecordId(referencePreservingModel),
      model: referencePreservingModel,
      switchedForProductReference: true,
    };
  }
  return {
    modelId: undefined,
    model: undefined,
    switchedForProductReference: false,
  };
}

function buildProductionInfographicModelExtraParams(params: {
  model?: any;
  referenceImageUrls: string[];
  referenceProductImageUrls?: string[];
  referenceCharacterImageUrls?: string[];
  referenceEnvironmentImageUrls?: string[];
  aspectRatio: string;
  base: Record<string, unknown>;
}): Record<string, unknown> {
  const extraParams: Record<string, unknown> = {
    ...params.base,
    reference_product_images: params.referenceProductImageUrls ?? [],
    reference_character_images: params.referenceCharacterImageUrls ?? [],
    reference_environment_images: params.referenceEnvironmentImageUrls ?? [],
  };
  const fields = parseModelInputFields(
    params.model
      ? {
          id: getMediaModelRecordId(params.model),
          name: String(
            params.model?.name ?? getMediaModelRecordId(params.model)
          ),
          provider: params.model?.provider
            ? String(params.model.provider)
            : undefined,
          configJson: params.model?.configJson,
        }
      : undefined
  );
  for (const field of fields) {
    const syncWith = inferModelInputSyncTarget(field as any);
    if (
      syncWith === "reference_images" &&
      params.referenceImageUrls.length > 0
    ) {
      extraParams[field.key] = field.maxItems
        ? params.referenceImageUrls.slice(0, field.maxItems)
        : params.referenceImageUrls;
    } else if (syncWith === "aspect_ratio") {
      extraParams[field.key] = params.aspectRatio;
    } else if (
      field.default !== undefined &&
      extraParams[field.key] === undefined &&
      field.type !== "image_urls"
    ) {
      extraParams[field.key] = field.default;
    }
  }
  return extraParams;
}

function buildProductionShotImageGenerationPrompt(params: {
  prompt: string;
  frameRole: "storyboard_grid" | "reference" | "start" | "stop";
  shotSceneGuide?: string;
  referenceUrls: string[];
  referenceContinuityImageUrls?: string[];
  referenceProductImageUrls?: string[];
  referenceCharacterImageUrls?: string[];
  referenceEnvironmentImageUrls?: string[];
}): string {
  const continuityUrls = new Set(params.referenceContinuityImageUrls ?? []);
  const productUrls = new Set(params.referenceProductImageUrls ?? []);
  const characterUrls = new Set(params.referenceCharacterImageUrls ?? []);
  const environmentUrls = new Set(params.referenceEnvironmentImageUrls ?? []);
  const referenceOrderMap = params.referenceUrls.map((url, index) => {
    const imageHandle = `@Image${index + 1}`;
    const role = continuityUrls.has(url)
      ? "GENERATED CONTINUITY ANCHOR"
      : productUrls.has(url)
        ? "PRODUCT SOURCE OF TRUTH"
        : characterUrls.has(url)
          ? "CHARACTER SOURCE OF TRUTH"
          : environmentUrls.has(url)
            ? "ENVIRONMENT / SCENE SOURCE OF TRUTH"
            : "REFERENCE IMAGE";
    return `${imageHandle}: ${role}`;
  });
  const productIndex = params.referenceUrls.findIndex(url =>
    productUrls.has(url)
  );
  const characterIndex = params.referenceUrls.findIndex(url =>
    characterUrls.has(url)
  );
  const environmentIndex = params.referenceUrls.findIndex(url =>
    environmentUrls.has(url)
  );
  const continuityHandles = params.referenceUrls
    .map((url, index) => (continuityUrls.has(url) ? `@Image${index + 1}` : ""))
    .filter(Boolean);
  const productHandle = productIndex >= 0 ? `@Image${productIndex + 1}` : "";
  const characterHandle =
    characterIndex >= 0 ? `@Image${characterIndex + 1}` : "";
  const environmentHandle =
    environmentIndex >= 0 ? `@Image${environmentIndex + 1}` : "";
  const productDetailLock = productHandle
    ? [
        `Product identity, geometry, materials, color, finish, visible part count, construction, and proportion are locked to ${productHandle}.`,
        "If written dimensions, category words, scene composition, or generated style conflict with the product reference image, the product reference image wins.",
        "Preserve the product's exact visible category, silhouette, bounding-box ratio, shelf/tier count, board thickness, leg/post thickness, open/closed side and back structure, hardware, color, and scale cues.",
        "Do not redesign, recolor, simplify, add drawers, add panels, remove shelves, change leg shapes, change material, or substitute a similar product.",
        "Do not stretch the furniture taller to fill the 9:16 frame. Leave vertical room around the product instead of turning it into a tall narrow shelf, bookcase, cabinet, or tower.",
      ].join(" ")
    : "";
  const characterIdentityLock = characterHandle
    ? [
        `Character identity and wardrobe are locked to ${characterHandle}.`,
        "Preserve the same person exactly: face shape, facial proportions, apparent age, skin tone, hair length, hair color, hairstyle, makeup level, body scale, and expression continuity.",
        "Preserve clothing exactly as visible in the character reference, including garment type, color, layering, collar/neckline, sleeves, and fit.",
        "Do not replace the person with a generic model, change ethnicity, change hairstyle, change outfit, or invent a different face. If the shot only needs hands or a partial body, keep visible clothing and skin cues consistent with the character reference.",
      ].join(" ")
    : "";
  const referenceRoleLock = [
    continuityHandles.length
      ? `${continuityHandles.join(", ")} are generated continuity anchors. Match their already-generated product instance, character likeness/wardrobe cues, room lighting, camera color science, perspective, and prop placement where compatible with the current shot. They are continuity anchors only; product/character/environment source references still win if any detail conflicts.`
      : "",
    productHandle
      ? `${productHandle} is product truth only and must define the product appearance.`
      : "",
    characterHandle
      ? `${characterHandle} is character truth only and must define identity, face, hair, and wardrobe.`
      : "",
    environmentHandle
      ? `${environmentHandle} is environment truth only and must define room mood, lighting, and background style without overriding product or character truth.`
      : "",
  ]
    .filter(Boolean)
    .join(" ");
  const frameRoleLabel =
    params.frameRole === "storyboard_grid"
      ? "STORYBOARD 3X3 GRID IMAGE"
      : `${params.frameRole.toUpperCase()} IMAGE`;
  const shotSceneLock = params.shotSceneGuide?.trim()
    ? [
        `This generation is for the CURRENT SHOT ${frameRoleLabel} ONLY.`,
        "Follow the current shot scene, script/voice, image intent, and video intent below as the highest-priority scene/action contract.",
        "Do not borrow the mood, action, prop state, or solution/result state from a different shot. Do not skip ahead to later shots.",
        params.shotSceneGuide.trim(),
      ].join("\n")
    : "";
  const promptHasSceneLock = params.prompt.includes("CURRENT SHOT SCENE LOCK:");
  const promptHasOrderMap = params.prompt.includes(
    "ATTACHED REFERENCE ORDER MAP:"
  );
  const promptHasRoleLock = params.prompt.includes("REFERENCE ROLE LOCK:");
  const promptHasProductLock = params.prompt.includes("PRODUCT DETAIL LOCK:");
  const promptHasCharacterLock = params.prompt.includes(
    "CHARACTER IDENTITY LOCK:"
  );

  return [
    params.prompt,
    shotSceneLock && !promptHasSceneLock
      ? ["CURRENT SHOT SCENE LOCK:", shotSceneLock].join("\n")
      : "",
    referenceOrderMap.length && !promptHasOrderMap
      ? [
          "ATTACHED REFERENCE ORDER MAP:",
          ...referenceOrderMap,
          "All @Image references in the prompt refer to this exact attachment order.",
        ].join("\n")
      : "",
    referenceRoleLock && !promptHasRoleLock
      ? ["REFERENCE ROLE LOCK:", referenceRoleLock].join("\n")
      : "",
    productDetailLock && !promptHasProductLock
      ? ["PRODUCT DETAIL LOCK:", productDetailLock].join("\n")
      : "",
    characterIdentityLock && !promptHasCharacterLock
      ? ["CHARACTER IDENTITY LOCK:", characterIdentityLock].join("\n")
      : "",
  ]
    .filter(Boolean)
    .join("\n\n");
}

function mergeProductionFrameReferenceUrls(input: {
  product?: string[];
  character?: string[];
  environment?: string[];
  continuity?: string[];
  fallback?: string[];
  limit: number;
}): string[] {
  const limit = Math.max(0, Math.floor(input.limit));
  if (limit <= 0) return [];
  const selected: string[] = [];
  const add = (url?: string | null) => {
    const cleanUrl = String(url ?? "").trim();
    if (!cleanUrl || selected.length >= limit || selected.includes(cleanUrl))
      return;
    selected.push(cleanUrl);
  };

  const product = input.product ?? [];
  const character = input.character ?? [];
  const environment = input.environment ?? [];
  const continuity = input.continuity ?? [];
  const fallback = input.fallback ?? [];

  add(product[0]);
  add(character[0]);
  for (const url of continuity) add(url);
  add(environment[0]);

  for (const url of [
    ...product.slice(1),
    ...character.slice(1),
    ...environment.slice(1),
    ...fallback,
  ]) {
    add(url);
    if (selected.length >= limit) break;
  }

  return selected;
}

function clearProductionConceptInfographicState(
  concept: ProductionStoryConceptOption
): ProductionStoryConceptOption {
  const {
    infographicTaskId: _infographicTaskId,
    infographicBackendTaskId: _infographicBackendTaskId,
    infographicProviderTaskId: _infographicProviderTaskId,
    infographicUrl: _infographicUrl,
    infographicStatus: _infographicStatus,
    infographicError: _infographicError,
    infographicSubmittedAt: _infographicSubmittedAt,
    infographicGeneratedAt: _infographicGeneratedAt,
    infographicModelId: _infographicModelId,
    ...rest
  } = concept;
  return {
    ...rest,
    infographicStatus: concept.infographicPrompt ? "prompt_ready" : "idle",
  };
}

function buildStoryOptionVideoBriefFromConcept(
  concept: ProductionStoryConceptOption
) {
  if (concept.voiceoverBeats?.length) {
    const locale = inferStoryConceptLocaleFromText(
      concept.voiceoverBeats.map(beat => beat.voiceoverScript)
    );
    return buildProductionStoryVideoBriefFromVoiceoverBeats({
      beats: concept.voiceoverBeats,
      locale,
      variationRecipe: concept.variationRecipe,
    });
  }
  const shots = concept.sceneTimeline.slice(0, 3).map((scene, index) => ({
    order: index + 1,
    startSec: index * 10,
    endSec: (index + 1) * 10,
    title: scene.title.slice(0, 240),
    videoPrompt: [
      "Vertical video 9:16, realistic product storytelling video, no text on screen, no subtitles.",
      `Story structure: ${concept.narrativeStructure || "Product storytelling"}.`,
      `Tone: ${concept.emotionalTone || "clear and trustworthy"}.`,
      scene.detail,
    ].join(" "),
    subShots: [
      scene.detail.slice(0, 500),
      (index === 0
        ? concept.hook
        : index === 1
          ? concept.angle
          : concept.useCase
      ).slice(0, 500),
      (index === 2
        ? "ปิดด้วยภาพสินค้าและ CTA ที่ไม่กล่าวอ้างเกินหลักฐาน"
        : "เชื่อมภาพกับ product truth และหลักฐานที่เลือก"
      ).slice(0, 500),
    ],
    thaiVoiceover: /^พูดเป็นภาษาไทยว่า/.test(scene.detail)
      ? scene.detail.slice(0, 600)
      : `พูดเป็นภาษาไทยว่า “${scene.detail.replace(/[“”"]/g, "").slice(0, 240)}”`,
  }));
  while (shots.length < 3) {
    const index = shots.length;
    shots.push({
      order: index + 1,
      startSec: index * 10,
      endSec: (index + 1) * 10,
      title:
        index === 0 ? "เปิด hook" : index === 1 ? "โชว์สินค้า" : "สรุป CTA",
      videoPrompt:
        "Vertical video 9:16, realistic product storytelling video, no text on screen, no subtitles.",
      subShots: [concept.hook, concept.angle, concept.useCase].map(item =>
        item.slice(0, 500)
      ),
      thaiVoiceover: `พูดเป็นภาษาไทยว่า “${(index === 0 ? concept.hook : index === 1 ? concept.angle : concept.useCase).replace(/[“”"]/g, "").slice(0, 240)}”`,
    });
  }
  return {
    schemaVersion: "1.0" as const,
    durationSec: 30 as const,
    aspectRatio: "9:16" as const,
    language: "th" as const,
    structureLabel: "30 วินาที | 3 Shot | Shot ละ 10 วินาที",
    noOnScreenText: true as const,
    shots,
  };
}

function buildMarketplaceHandoffFromStoryConcepts(params: {
  goal: ProductionGoal;
  productTruthContext: Record<string, unknown>;
  options: ProductionStoryConceptOption[];
  source: "llm_synthesized" | "local_fallback";
}): MarketplaceStorytellingHandoff | null {
  const context = getPrimaryProductPlanningContext(
    params.productTruthContext,
    params.goal
  );
  const sourceUrl = context.sourceUrl;
  const affiliateUrl = context.affiliateUrl || null;
  const platform =
    context.platform === "tiktok_shop" ? "tiktok_shop" : "shopee";
  if (!sourceUrl || !/^https?:\/\//i.test(sourceUrl)) return null;
  const evidenceIds = ["title:product", "description:product", "image:product"];
  const storyOptions: MarketplaceStorytellingHandoff["storyOptions"] =
    params.options.slice(0, 4).map((concept, index) => {
      const meta = concept.storyOptionId
        ? MARKETPLACE_STORY_DIMENSION_META[concept.storyOptionId]
        : MARKETPLACE_STORY_DIMENSION_META[
            MARKETPLACE_STORY_DIMENSION_ORDER[index]
          ];
      return {
        id: concept.storyOptionId ?? MARKETPLACE_STORY_DIMENSION_ORDER[index],
        title: meta?.titleTh ?? concept.title,
        audience: concept.audience,
        customerNeed: concept.painPoint,
        problemToSolve: concept.painPoint,
        useCase: concept.useCase,
        angle: concept.angle,
        storyFormat:
          concept.storyDimension === "quick_demo"
            ? ("sales_demo" as const)
            : concept.storyDimension === "objection_trust"
              ? ("product_review" as const)
              : ("customer_journey" as const),
        journeyStages:
          concept.storyDimension === "objection_trust"
            ? ([
                "awareness",
                "objection_handling",
                "trust_building",
                "conversion_cta",
              ] as MarketplaceStorytellingHandoff["customerJourneyStages"])
            : ([
                "problem_recognition",
                "consideration",
                "proof_review_demo",
                "conversion_cta",
              ] as MarketplaceStorytellingHandoff["customerJourneyStages"]),
        hook: concept.hook,
        storyboardOutline: concept.sceneTimeline
          .map(scene => `${scene.timeRange} ${scene.title}: ${scene.detail}`)
          .slice(0, 8),
        primaryClaimIds: [],
        evidenceIds,
        confidence: 0.62,
        autoSelected: index === 0,
        decisionReason:
          params.source === "llm_synthesized"
            ? "Synthesized by Media Studio planner because stored storyOptions were incomplete."
            : "Generated by deterministic Media Studio fallback because stored storyOptions were incomplete.",
        source:
          params.source === "llm_synthesized"
            ? ("ai_detected" as const)
            : ("mixed" as const),
        userAdditions: [],
        videoBrief:
          concept.videoBrief && typeof concept.videoBrief === "object"
            ? (concept.videoBrief as any)
            : buildStoryOptionVideoBriefFromConcept(concept),
      };
    });
  return {
    schemaVersion: "1.0",
    sourceCaptureIds: [],
    insightIds: [],
    productName:
      context.productName ||
      params.goal.title ||
      params.goal.summary.slice(0, 120) ||
      "Marketplace product",
    sourceUrl,
    affiliateUrl,
    platform,
    storyFormat: "customer_journey",
    readiness: "ready_with_warnings",
    blockers: ["media_studio_synthesized_story_options_need_review"],
    customerJourneyStages: [
      "awareness",
      "problem_recognition",
      "consideration",
      "proof_review_demo",
      "conversion_cta",
    ],
    storyOptions,
    claims: [],
    selectedImages: [],
    videoBrief: undefined,
    evidenceIds,
    confidence: 0.62,
  };
}

function buildMediaStudioStorytellingInsightSyncRequest(params: {
  handoff: MarketplaceStorytellingHandoff;
  productTruthContext: Record<string, unknown>;
  generationSeed: string;
  provider: "server_ai" | "manual";
}) {
  const context = getPrimaryProductPlanningContext(params.productTruthContext, {
    summary: params.handoff.productName,
  });
  const sourceIdentity = {
    platform: params.handoff.platform,
    canonicalSourceUrl: params.handoff.sourceUrl,
    externalProductId: context.externalProductId || undefined,
    externalShopId: context.externalShopId || undefined,
  };
  const semanticPayloadHash = buildProductionStableHash({
    sourceIdentity,
    insightType: "storytelling_handoff",
    purpose: "media_studio_story_options_v1",
  }).slice(0, 40);
  return {
    extensionVersion: "media-studio",
    idempotencyKey: `media-studio:${params.handoff.platform}:${semanticPayloadHash}:storytelling_handoff`,
    schemaVersion: "1.0" as const,
    insightCreatedAt: new Date().toISOString(),
    payloadHash: semanticPayloadHash,
    source: {
      platform: params.handoff.platform,
      url: params.handoff.sourceUrl,
      affiliateUrl: params.handoff.affiliateUrl ?? undefined,
      capturedAt: new Date().toISOString(),
      marketplaceProductId: context.productId || undefined,
    },
    insightType: "storytelling_handoff" as const,
    provider: params.provider,
    status: "ready" as const,
    parentInsightIds: [],
    metadata: {
      providerDecision: params.provider,
      sanitizerVersion: "media-studio-2026-05-24",
      generationRunId: `media_studio_story_options:${params.generationSeed}`,
      inputEvidenceIds: params.handoff.evidenceIds,
      sourceIds: {
        externalProductId: sourceIdentity.externalProductId,
        externalShopId: sourceIdentity.externalShopId,
        canonicalSourceUrl: sourceIdentity.canonicalSourceUrl,
      },
      sourceIdentity,
      sourceIdentityHash: buildProductionStableHash(sourceIdentity).slice(
        0,
        20
      ),
      semanticKey: `media-studio:${params.handoff.platform}:storytelling_handoff:${semanticPayloadHash}`,
      semanticPayloadHash,
      storyOptionCount: params.handoff.storyOptions.length,
      storyOptionVideoBriefCount: params.handoff.storyOptions.filter(
        option => option.videoBrief
      ).length,
    },
    payload: params.handoff,
    rawCaptureIncluded: false,
    rawCapture: undefined,
  };
}
const MEDIA_STUDIO_CREDIT_ORIGIN = "media_studio" as const;
const HISTORY_GALLERY_PAGE_SIZE = 30;
const LIBRARY_SEARCH_PAGE_SIZE = 30;
const MARKETPLACE_IMAGE_PAGE_SIZE = 30;
const MEDIA_STUDIO_RIGHT_PANEL_COLLAPSED_KEY =
  "smartspec_media_studio_right_panel_collapsed";
const HISTORY_GALLERY_MEDIA_TASK_MAX = 100;
const HISTORY_GALLERY_PUBLIC_GALLERY_MAX = 100;
const HISTORY_GALLERY_SHARED_GROUP_MAX = 50;
const mediaStudioGeneratedAssetResolver = new WebAssetResolver();

function isManagedMediaStudioAssetUrl(value: string): boolean {
  const trimmed = value.trim();
  if (
    trimmed.startsWith("/api/storage/files/") ||
    trimmed.startsWith("/uploads/") ||
    trimmed.startsWith("/api/v1/media/files/") ||
    trimmed.startsWith("data:") ||
    trimmed.startsWith("blob:")
  ) {
    return true;
  }
  if (typeof window === "undefined" || !/^https?:\/\//i.test(trimmed)) {
    return false;
  }
  try {
    const parsed = new URL(trimmed);
    return (
      parsed.origin === window.location.origin &&
      (parsed.pathname.startsWith("/api/storage/files/") ||
        parsed.pathname.startsWith("/uploads/") ||
        parsed.pathname.startsWith("/api/v1/media/files/"))
    );
  } catch {
    return false;
  }
}

async function persistGeneratedStoryboardAudioUrl(
  url: string
): Promise<string> {
  const normalizedUrl = url.trim();
  if (
    !/^https?:\/\//i.test(normalizedUrl) ||
    isManagedMediaStudioAssetUrl(normalizedUrl)
  ) {
    return normalizedUrl;
  }
  const result = await mediaStudioGeneratedAssetResolver.importRemoteAsset(
    normalizedUrl,
    { mediaType: "audio" }
  );
  return result.uri;
}

function getDefaultSplitToolsPanelWidth(): number {
  if (typeof window === "undefined") return 560;
  if (window.innerWidth <= 1024) {
    return Math.max(320, window.innerWidth - 24);
  }
  return Math.min(760, Math.max(420, Math.round(window.innerWidth * 0.38)));
}

function clampSplitToolsPanelWidth(width: number): number {
  if (typeof window === "undefined") return width;
  const minWidth = window.innerWidth <= 640 ? 320 : 360;
  const maxWidth = Math.min(920, Math.max(minWidth, window.innerWidth - 48));
  return Math.min(Math.max(width, minWidth), maxWidth);
}

function clampSplitToolsPanelTop(top: number): number {
  if (typeof window === "undefined") return top;
  const minTop = 12;
  const maxTop = Math.max(minTop, window.innerHeight - 300);
  return Math.min(Math.max(top, minTop), maxTop);
}

function getDefaultFloatingPreviewFrame(): FloatingPreviewFrame {
  if (typeof window === "undefined") {
    return { x: 80, y: 80, width: 560, height: 560 };
  }

  const width = Math.min(
    720,
    Math.max(360, Math.round(window.innerWidth * 0.44))
  );
  const height = Math.min(
    720,
    Math.max(360, Math.round(window.innerHeight * 0.7))
  );
  return {
    x: Math.max(16, window.innerWidth - width - 32),
    y: 96,
    width,
    height,
  };
}

function clampFloatingPreviewFrame(
  frame: FloatingPreviewFrame
): FloatingPreviewFrame {
  if (typeof window === "undefined") {
    return frame;
  }

  const minWidth = 320;
  const minHeight = 260;
  const maxWidth = Math.max(minWidth, window.innerWidth - 24);
  const maxHeight = Math.max(minHeight, window.innerHeight - 24);
  const width = Math.min(Math.max(frame.width, minWidth), maxWidth);
  const height = Math.min(Math.max(frame.height, minHeight), maxHeight);
  const x = Math.min(
    Math.max(frame.x, 12),
    Math.max(12, window.innerWidth - width - 12)
  );
  const y = Math.min(
    Math.max(frame.y, 12),
    Math.max(12, window.innerHeight - height - 12)
  );

  return { x, y, width, height };
}

function isMarketplaceStorytellingHandoff(
  value: unknown
): value is MarketplaceStorytellingHandoff {
  const payload =
    value && typeof value === "object" ? (value as Record<string, any>) : null;
  return Boolean(
    payload &&
    payload.schemaVersion === "1.0" &&
    typeof payload.productName === "string" &&
    typeof payload.sourceUrl === "string" &&
    Array.isArray(payload.customerJourneyStages) &&
    Array.isArray(payload.selectedImages) &&
    Array.isArray(payload.claims)
  );
}

function buildMarketplaceStorytellingPrompt(
  handoff: MarketplaceStorytellingHandoff
): string {
  const recommendedOptions = (handoff.storyOptions || [])
    .slice()
    .sort(
      (a, b) =>
        Number(b.autoSelected) - Number(a.autoSelected) ||
        b.confidence - a.confidence
    )
    .slice(0, 4);
  const storyOptions = recommendedOptions
    .map((option, index) => {
      const optionVideo =
        option.videoBrief?.shots
          ?.map(shot =>
            [
              `Shot ${shot.order} (${shot.startSec}-${shot.endSec}s): ${shot.title}`,
              `Video Prompt: ${shot.videoPrompt}`,
              `Sub-shots: ${shot.subShots.join(" | ")}`,
              shot.thaiVoiceover,
            ].join("\n")
          )
          .join("\n") || "";
      return [
        `${index + 1}. ${option.title}${option.autoSelected ? " (recommended)" : ""}`,
        `Audience: ${option.audience}`,
        `Need/problem: ${option.customerNeed} / ${option.problemToSolve}`,
        `Use case: ${option.useCase}`,
        `Hook: ${option.hook}`,
        `Journey: ${option.journeyStages.join(" -> ")}`,
        `Storyboard: ${option.storyboardOutline.join(" | ")}`,
        optionVideo
          ? `Video storyboard (${option.videoBrief?.structureLabel || "30s"}):\n${optionVideo}`
          : "",
        option.userAdditions?.length
          ? `User-confirmed additions: ${option.userAdditions.map(addition => `${addition.category}: ${addition.values.join(" / ")}`).join(" | ")}`
          : "",
      ]
        .filter(Boolean)
        .join("\n");
    })
    .join("\n\n");
  const supportedClaims = handoff.claims
    .filter(
      claim => claim.status === "supported" || claim.status === "user_approved"
    )
    .map(claim => `- ${claim.text}`)
    .join("\n");
  return [
    `Marketplace Product Storytelling Draft: ${handoff.productName}`,
    `Source: ${handoff.sourceUrl}`,
    handoff.affiliateUrl ? `Affiliate: ${handoff.affiliateUrl}` : "",
    `Format: ${handoff.storyFormat}`,
    `Readiness: ${handoff.readiness}`,
    `Customer journey: ${handoff.customerJourneyStages.join(" -> ")}`,
    storyOptions ? `AI customer journey/story options:\n${storyOptions}` : "",
    supportedClaims ? `Evidence-backed claims:\n${supportedClaims}` : "",
    "Create a draft only. Keep product identity faithful to the reference images and do not invent unsupported product claims.",
  ]
    .filter(Boolean)
    .join("\n\n");
}

function buildMarketplaceStorytellingReferenceImages(
  handoff: MarketplaceStorytellingHandoff
): ReferenceImage[] {
  return handoff.selectedImages
    .filter(image => image.url && image.fidelity !== "mismatch_risk")
    .slice(0, 8)
    .map((image, index) => ({
      url: image.url,
      name: `Marketplace ${image.role || "reference"} ${index + 1}`,
      marketplaceProduct: {
        platform: handoff.platform,
        productName: handoff.productName,
        sourceUrl: handoff.sourceUrl,
        affiliateUrl: handoff.affiliateUrl ?? null,
      },
    }));
}
