function isGeminiOmniVideoMediaModel(
  model: any,
  selectedModelId: string
): boolean {
  const config = parseMediaModelConfig(model?.configJson);
  const aliases = Array.isArray(config?.aliases)
    ? config.aliases
    : Array.isArray(model?.aliases)
      ? model.aliases
      : [];
  const candidates = [
    selectedModelId,
    model?.id,
    model?.modelId,
    model?.name,
    model?.displayName,
    model?.provider,
    config?.modelId,
    config?.kieModelId,
    config?.apiModel,
    ...aliases,
  ]
    .map(value =>
      String(value ?? "")
        .trim()
        .toLowerCase()
    )
    .filter(Boolean);
  return candidates.some(
    value =>
      value === GEMINI_OMNI_VIDEO_MODEL_ID ||
      value === "gemini-omni" ||
      value.includes("gemini omni") ||
      value.includes("gemini-omni")
  );
}

