interface StoryboardReviewDraft {
  version: 1;
  reviewId?: number | null;
  name?: string | null;
  updatedAt: number;
  taskIds: string[];
  selectedTaskIds: string[];
  tasks: GenerationTask[];
  companionAudio: StoryboardCompanionAudioCandidate[];
  companionAudioUpdatedAt?: number | null;
  compoundStatus: string | null;
  projectLink: string | null;
  renderJobId: string | null;
  marketplaceContext?: MarketplaceProductReferenceContext | null;
  productionContext?: StoryboardProductionContext | null;
  conceptDetails?: string | null;
  storyboardGuide?: string | null;
  voiceoverFullScript?: string | null;
  useVoiceoverScriptAsConcept?: boolean;
}

const STORYBOARD_REVIEW_DRAFT_STORAGE_KEY =
  "smartspec_media_studio_storyboard_review_draft_v1";
const STORYBOARD_REVIEW_DRAFT_TTL_MS = 3 * 24 * 60 * 60 * 1000;
const STORYBOARD_REVIEW_CLIENT_DEBUG_BUILD =
  "media-studio-storyboard-audio-debug-20260527-2235";

function readStoryboardReviewDraft(): StoryboardReviewDraft | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(
      STORYBOARD_REVIEW_DRAFT_STORAGE_KEY
    );
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<StoryboardReviewDraft>;
    if (
      parsed.version !== 1 ||
      !Array.isArray(parsed.taskIds) ||
      !Array.isArray(parsed.tasks)
    ) {
      return null;
    }
    if (
      typeof parsed.updatedAt !== "number" ||
      Date.now() - parsed.updatedAt > STORYBOARD_REVIEW_DRAFT_TTL_MS
    ) {
      window.localStorage.removeItem(STORYBOARD_REVIEW_DRAFT_STORAGE_KEY);
      return null;
    }
    const companionAudioUpdatedAt =
      typeof parsed.companionAudioUpdatedAt === "number"
        ? parsed.companionAudioUpdatedAt
        : null;
    const companionAudio =
      companionAudioUpdatedAt &&
      companionAudioUpdatedAt > 0 &&
      Array.isArray(parsed.companionAudio)
        ? (parsed.companionAudio as StoryboardCompanionAudioCandidate[])
        : [];
    return {
      version: 1,
      reviewId: typeof parsed.reviewId === "number" ? parsed.reviewId : null,
      name: typeof parsed.name === "string" ? parsed.name : null,
      updatedAt: parsed.updatedAt,
      taskIds: parsed.taskIds.filter(
        (id): id is string => typeof id === "string" && id.trim().length > 0
      ),
      selectedTaskIds: Array.isArray(parsed.selectedTaskIds)
        ? parsed.selectedTaskIds.filter(
            (id): id is string => typeof id === "string" && id.trim().length > 0
          )
        : [],
      tasks: parsed.tasks as GenerationTask[],
      companionAudio,
      companionAudioUpdatedAt,
      compoundStatus:
        typeof parsed.compoundStatus === "string"
          ? parsed.compoundStatus
          : null,
      projectLink:
        typeof parsed.projectLink === "string" ? parsed.projectLink : null,
      renderJobId:
        typeof parsed.renderJobId === "string" ? parsed.renderJobId : null,
      marketplaceContext: parsed.marketplaceContext ?? null,
      productionContext: parsed.productionContext ?? null,
      conceptDetails:
        typeof parsed.conceptDetails === "string"
          ? parsed.conceptDetails
          : null,
      storyboardGuide:
        typeof parsed.storyboardGuide === "string"
          ? parsed.storyboardGuide
          : null,
      voiceoverFullScript:
        typeof parsed.voiceoverFullScript === "string"
          ? parsed.voiceoverFullScript
          : null,
      useVoiceoverScriptAsConcept: Boolean(parsed.useVoiceoverScriptAsConcept),
    };
  } catch {
    return null;
  }
}

function writeStoryboardReviewDraft(draft: StoryboardReviewDraft): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(
      STORYBOARD_REVIEW_DRAFT_STORAGE_KEY,
      JSON.stringify(draft)
    );
  } catch {
    // Ignore storage quota/private mode failures; active in-memory state still works.
  }
}

function buildStoryboardReviewDebugSource(
  source: string,
  draft: Partial<StoryboardReviewDraft> | null | undefined
) {
  const companionAudio = Array.isArray(draft?.companionAudio)
    ? draft.companionAudio
    : [];
  return {
    source,
    build: STORYBOARD_REVIEW_CLIENT_DEBUG_BUILD,
    reviewId: typeof draft?.reviewId === "number" ? draft.reviewId : null,
    updatedAt: typeof draft?.updatedAt === "number" ? draft.updatedAt : null,
    companionAudioUpdatedAt:
      typeof draft?.companionAudioUpdatedAt === "number"
        ? draft.companionAudioUpdatedAt
        : null,
    audioCount: companionAudio.length,
    audioIds: companionAudio.map(audio => audio.id).slice(0, 5),
    audioTitles: companionAudio.map(audio => audio.title).slice(0, 5),
  };
}

function clearStoryboardReviewDraft(): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.removeItem(STORYBOARD_REVIEW_DRAFT_STORAGE_KEY);
  } catch {
    // Ignore storage failures.
  }
}

function formatStoryboardReviewNameTimestamp(now = new Date()): string {
  const pad = (value: number) => String(value).padStart(2, "0");
  return (
    [now.getFullYear(), pad(now.getMonth() + 1), pad(now.getDate())].join("-") +
    ` ${pad(now.getHours())}.${pad(now.getMinutes())}`
  );
}

function getMarketplaceProductNameForStoryboardReview(
  context: MarketplaceProductReferenceContext | null | undefined
): string {
  if (!context) return "";
  const record = context as Record<string, unknown>;
  return firstNonEmpty(
    context.productName,
    readStringValue(record, "title"),
    readStringValue(record, "product_title"),
    readStringValue(record, "productName"),
    readStringValue(record, "name")
  );
}

function buildSplitStoryboardReviewProjectName(input: {
  marketplaceContext?: MarketplaceProductReferenceContext | null;
  productionProjectName?: string | null;
  fallback?: string;
  now?: Date;
}): string {
  const baseName = firstNonEmpty(
    getMarketplaceProductNameForStoryboardReview(input.marketplaceContext),
    input.productionProjectName,
    input.fallback,
    "Storyboard Review"
  );
  return sanitizeProjectName(
    `${baseName} ${formatStoryboardReviewNameTimestamp(input.now)}`
  );
}

function buildStoryboardProductionContext(input: {
  productionRunId?: string | null;
  productionProjectTitle?: string | null;
  concept?: ProductionStoryConceptOption | null;
  conceptDetails?: string | null;
  storyboardGuide?: string | null;
  voiceoverFullScript?: string | null;
  sourceGridUrl?: string | null;
  sourceShotId?: string | null;
  sourceShotTitle?: string | null;
  sourceShotTimeRange?: string | null;
  sourceShotScript?: string | null;
  sourceShotVideoPrompt?: string | null;
}): StoryboardProductionContext | null {
  const concept = input.concept;
  const context: StoryboardProductionContext = {
    productionRunId: firstNonEmpty(input.productionRunId) || null,
    productionProjectTitle: firstNonEmpty(input.productionProjectTitle) || null,
    productionStoryConceptId:
      firstNonEmpty(concept?.id, concept?.storyOptionId) || null,
    productionStoryConceptTitle: firstNonEmpty(concept?.title) || null,
    productionStoryConceptAngle: firstNonEmpty(concept?.angle) || null,
    productionStoryConceptDetails: firstNonEmpty(input.conceptDetails) || null,
    videoConcept:
      firstNonEmpty(
        input.conceptDetails,
        concept?.visualSummary,
        concept?.videoBrief ? JSON.stringify(concept.videoBrief) : null
      ) || null,
    voiceoverFullScript: firstNonEmpty(input.voiceoverFullScript) || null,
    storyboardGuide: firstNonEmpty(input.storyboardGuide) || null,
    sourceGridUrl: firstNonEmpty(input.sourceGridUrl) || null,
    sourceShotId: firstNonEmpty(input.sourceShotId) || null,
    sourceShotTitle: firstNonEmpty(input.sourceShotTitle) || null,
    sourceShotTimeRange: firstNonEmpty(input.sourceShotTimeRange) || null,
    sourceShotScript: firstNonEmpty(input.sourceShotScript) || null,
    sourceShotVideoPrompt: firstNonEmpty(input.sourceShotVideoPrompt) || null,
  };
  const compacted = Object.fromEntries(
    Object.entries(context).filter(
      ([, value]) => typeof value === "string" && value.trim().length > 0
    )
  ) as StoryboardProductionContext;
  return Object.keys(compacted).length > 0 ? compacted : null;
}

