const PROMPT_REVIEW_LOCKED_FIELD_PRIORITY = [
  "aspect_ratio",
  "deliverable_type",
  "exact_text",
  "source_image_path",
  "target_language",
  "image_style",
  "render_size",
  "quality",
  "topic",
];

const humanizePromptReviewIdentifier = (
  value: string,
  locale: PromptReviewLocale
): string => {
  const text = value.replace(/[_-]+/g, " ").trim();
  if (!text) return "";
  if (locale === "th") return text;
  return text.replace(/\b\w/g, match => match.toUpperCase());
};

const formatPromptReviewLookup = (
  value: string,
  locale: PromptReviewLocale,
  dictionary: Record<PromptReviewLocale, Record<string, string>>
): string =>
  dictionary[locale]?.[value] || humanizePromptReviewIdentifier(value, locale);

const formatPromptReviewValue = (
  fieldName: string,
  value: unknown,
  locale: PromptReviewLocale
): string => {
  if (Array.isArray(value)) {
    if (fieldName === "source_image_path") {
      return locale === "th"
        ? `${value.length} รูป`
        : `${value.length} reference image${value.length === 1 ? "" : "s"}`;
    }
    return locale === "th"
      ? `${value.length} รายการ`
      : `${value.length} item${value.length === 1 ? "" : "s"}`;
  }
  if (typeof value === "boolean") {
    return locale === "th" ? (value ? "เปิด" : "ปิด") : value ? "On" : "Off";
  }
  const text = String(value ?? "").trim();
  if (!text) return "";
  const localized = PROMPT_REVIEW_VALUE_LABELS[locale]?.[text] || text;
  return localized.length > 60 ? `${localized.slice(0, 57)}...` : localized;
};

const formatPromptReviewLockedParams = (
  lockedUserParams: Record<string, unknown> | null,
  locale: PromptReviewLocale
): string[] => {
  const fields = promptReviewObject(lockedUserParams?.fields);
  const fieldNames = promptReviewStringArray(lockedUserParams?.field_names);
  const rawNames =
    fieldNames.length > 0 ? fieldNames : Object.keys(fields || {});
  const names = rawNames
    .filter(name => name !== "topic" || rawNames.length === 1)
    .sort((left, right) => {
      const leftIndex = PROMPT_REVIEW_LOCKED_FIELD_PRIORITY.indexOf(left);
      const rightIndex = PROMPT_REVIEW_LOCKED_FIELD_PRIORITY.indexOf(right);
      return (
        (leftIndex === -1 ? 99 : leftIndex) -
        (rightIndex === -1 ? 99 : rightIndex)
      );
    });
  return names
    .slice(0, 8)
    .map(name => {
      const entry = promptReviewObject(fields?.[name]);
      const value = entry?.normalized ?? entry?.requested;
      const formattedValue = formatPromptReviewValue(name, value, locale);
      const label = formatPromptReviewLookup(
        name,
        locale,
        PROMPT_REVIEW_FIELD_LABELS
      );
      return formattedValue ? `${label}: ${formattedValue}` : "";
    })
    .filter(Boolean);
};

const normalizePromptReviewSummary = (
  value: unknown
): PromptReviewSummary | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const review = value as Record<string, unknown>;
  const rawQualityScore = review.qualityScore;
  const qualityScore = Number(rawQualityScore);
  return {
    status: typeof review.status === "string" ? review.status : null,
    approved: typeof review.approved === "boolean" ? review.approved : null,
    requiresRevision:
      typeof review.requiresRevision === "boolean"
        ? review.requiresRevision
        : null,
    missingInputs: promptReviewStringArray(review.missingInputs),
    clarifyingQuestions: promptReviewStringArray(review.clarifyingQuestions),
    referenceResearchStatus:
      typeof review.referenceResearchStatus === "string"
        ? review.referenceResearchStatus
        : null,
    selectedSubagents: promptReviewStringArray(review.selectedSubagents),
    qualityScore:
      rawQualityScore === null || rawQualityScore === undefined
        ? null
        : Number.isFinite(qualityScore)
          ? qualityScore
          : null,
    failedChecks: promptReviewStringArray(review.failedChecks),
    lockedUserParams: promptReviewObject(review.lockedUserParams),
    referenceSearchQueries: promptReviewStringArray(
      review.referenceSearchQueries
    ),
    referenceNextAction:
      typeof review.referenceNextAction === "string"
        ? review.referenceNextAction
        : null,
  };
};

function buildSkillImprovementProposalFromPromptReview(input: {
  promptReview: PromptReviewSummary | null;
  promptText: string;
  skillId: string;
  activeTab: MediaType;
  dynamicFormValues: Record<string, any>;
  referenceImageCount: number;
  locale: PromptReviewLocale;
}): MediaStudioSkillImprovementProposal | null {
  if (!isMediaStudioAutoLearningSkill(input.skillId)) {
    return null;
  }

  const issues: SkillImprovementIssue[] = [];
  const proposedChanges: SkillImprovementProposedChange[] = [];
  const promptText = input.promptText.trim();
  const lowerPrompt = promptText.toLowerCase();
  const isThai = input.locale === "th";
  const targetFile = "skill.md";

  const addIssue = (
    issue: SkillImprovementIssue,
    change: SkillImprovementProposedChange
  ) => {
    if (!issues.some(item => item.id === issue.id)) {
      issues.push(issue);
      proposedChanges.push(change);
    }
  };

  for (const failedCheck of input.promptReview?.failedChecks ?? []) {
    addIssue(
      {
        id: `prompt_review_${failedCheck}`,
        severity: failedCheck.includes("safety")
          ? "high"
          : failedCheck.includes("quality")
            ? "medium"
            : "high",
        title: isThai
          ? `Prompt QA พบปัญหา: ${formatPromptReviewLookup(failedCheck, input.locale, PROMPT_REVIEW_CHECK_LABELS)}`
          : `Prompt QA issue: ${formatPromptReviewLookup(failedCheck, input.locale, PROMPT_REVIEW_CHECK_LABELS)}`,
        evidence: failedCheck,
        recommendation: isThai
          ? "เพิ่มกฎใน skill ให้ล็อกข้อกำกับนี้ชัดขึ้น และให้ QA loop ตรวจซ้ำก่อนส่ง prompt"
          : "Strengthen this rule in the skill and make the QA loop check it before returning a prompt.",
        affectedSection: "Prompt QA / final review rules",
      },
      {
        title: isThai
          ? `เพิ่ม rule สำหรับ ${formatPromptReviewLookup(failedCheck, input.locale, PROMPT_REVIEW_CHECK_LABELS)}`
          : `Add rule for ${formatPromptReviewLookup(failedCheck, input.locale, PROMPT_REVIEW_CHECK_LABELS)}`,
        reason: isThai
          ? "ผลตรวจ Prompt QA ระบุว่าพรอมต์ยังขาดข้อกำกับนี้"
          : "Prompt QA reported that this guard is missing or weak.",
        targetFile,
        targetSection: "Quality gates",
        risk: "medium",
      }
    );
  }

  for (const missingInput of input.promptReview?.missingInputs ?? []) {
    addIssue(
      {
        id: `missing_input_${missingInput}`,
        severity: "medium",
        title: isThai
          ? `ข้อมูลที่ skill ควรถามเพิ่ม: ${formatPromptReviewLookup(missingInput, input.locale, PROMPT_REVIEW_FIELD_LABELS)}`
          : `Skill should ask for: ${formatPromptReviewLookup(missingInput, input.locale, PROMPT_REVIEW_FIELD_LABELS)}`,
        evidence: missingInput,
        recommendation: isThai
          ? "เพิ่มคำถาม/required hint ใน skill เมื่อข้อมูลนี้จำเป็นต่อ fidelity"
          : "Add a clarifying question or required hint when this input is needed for fidelity.",
        affectedSection: "Input requirements",
      },
      {
        title: isThai
          ? "เพิ่ม missing-input guidance"
          : "Add missing-input guidance",
        reason: isThai
          ? "ลดโอกาสที่ Auto Prompt สร้างพรอมต์ไม่ครบเพราะข้อมูลตั้งต้นไม่พอ"
          : "Reduce incomplete Auto Prompt output when required source details are missing.",
        targetFile,
        targetSection: "Input preflight",
        risk: "low",
      }
    );
  }

  if (/^```?json\b/i.test(promptText) || /^[\[{]/.test(promptText)) {
    addIssue(
      {
        id: "json_output_leak",
        severity: "high",
        title: isThai
          ? "ผลลัพธ์ Auto Prompt ยังมีรูปแบบ JSON หลุดมา"
          : "Auto Prompt output leaked JSON",
        evidence: promptText.slice(0, 240),
        recommendation: isThai
          ? "เพิ่ม output contract ให้ส่งกลับเฉพาะ prompt text ปกติ และห้าม markdown/json wrapper"
          : "Add an output contract requiring plain prompt text only, with no markdown or JSON wrapper.",
        affectedSection: "Output format",
      },
      {
        title: isThai
          ? "ล็อก output เป็น plain text เท่านั้น"
          : "Lock output to plain text only",
        reason: isThai
          ? "ผู้ใช้ต้องนำ prompt ไป generate ต่อทันที ไม่ควรต้องลบ JSON เอง"
          : "Users should be able to generate directly without manually removing JSON.",
        targetFile,
        targetSection: "Output contract",
        risk: "low",
      }
    );
  }

  if (
    input.referenceImageCount > 0 &&
    !/(reference|อ้างอิง|product|สินค้า|fidelity|lock)/i.test(promptText)
  ) {
    addIssue(
      {
        id: "weak_reference_fidelity_lock",
        severity: "high",
        title: isThai
          ? "พรอมต์ยังล็อกความเหมือนภาพอ้างอิงไม่ชัด"
          : "Reference fidelity lock is weak",
        recommendation: isThai
          ? "เพิ่มกฎให้ prompt ต้องระบุ product/character reference lock ทุกครั้งที่มีรูปอ้างอิง"
          : "Require product/character reference lock language whenever reference images are attached.",
        affectedSection: "Reference fidelity",
      },
      {
        title: isThai
          ? "เพิ่ม reference fidelity guard"
          : "Add reference fidelity guard",
        reason: isThai
          ? "ช่วยลดการเปลี่ยนรูปทรง สี วัสดุ ตัวละคร หรือสินค้าเมื่อ generate ภาพ"
          : "Reduces shape, material, color, product, and character drift during generation.",
        targetFile,
        targetSection: "Reference fidelity rules",
        risk: "medium",
      }
    );
  }

  if (
    input.skillId.includes("furniture") &&
    !/(drawer|shelf|leg|caster|handle|material|finish|texture|ลิ้นชัก|ชั้น|ขา|ล้อ|มือจับ|วัสดุ)/i.test(
      promptText
    )
  ) {
    addIssue(
      {
        id: "weak_furniture_geometry_material_lock",
        severity: "high",
        title: isThai
          ? "พรอมต์ยังไม่ล็อก geometry/material ของเฟอร์นิเจอร์พอ"
          : "Furniture geometry/material lock is weak",
        recommendation: isThai
          ? "เพิ่ม rule ให้ระบุจำนวนชิ้นส่วน วัสดุ สี ผิวสัมผัส และโครงสร้างที่มองเห็นได้จาก reference"
          : "Add rules to preserve visible part counts, material, color, texture, and structure from references.",
        affectedSection: "Furniture product fidelity",
      },
      {
        title: isThai
          ? "เพิ่ม furniture geometry/material lock"
          : "Add furniture geometry/material lock",
        reason: isThai
          ? "ป้องกันสินค้าเฟอร์นิเจอร์กลายเป็นรุ่นอื่นหรือเปลี่ยนชิ้นส่วนสำคัญ"
          : "Prevents furniture from becoming a different SKU or losing critical product parts.",
        targetFile,
        targetSection: "Product fidelity rules",
        risk: "medium",
      }
    );
  }

  if (
    input.skillId.includes("cosmatic") &&
    !/(label|logo|packaging|bottle|tube|jar|shade|ฉลาก|โลโก้|บรรจุภัณฑ์|ขวด|หลอด|กระปุก)/i.test(
      promptText
    )
  ) {
    addIssue(
      {
        id: "weak_cosmetic_packaging_lock",
        severity: "high",
        title: isThai
          ? "พรอมต์ยังไม่ล็อกบรรจุภัณฑ์/ฉลากของสินค้าเครื่องสำอางพอ"
          : "Cosmetic packaging/label lock is weak",
        recommendation: isThai
          ? "เพิ่ม rule ให้รักษารูปทรงบรรจุภัณฑ์ สี ฉลาก โลโก้ และ shade/product variant"
          : "Add rules to preserve package shape, color, label, logo, and shade/product variant.",
        affectedSection: "Cosmetic product fidelity",
      },
      {
        title: isThai
          ? "เพิ่ม cosmetic packaging fidelity lock"
          : "Add cosmetic packaging fidelity lock",
        reason: isThai
          ? "ลดปัญหา label/logo/สีรุ่นสินค้าเพี้ยนจากภาพต้นฉบับ"
          : "Reduces label, logo, color, and variant drift from the source product.",
        targetFile,
        targetSection: "Product fidelity rules",
        risk: "medium",
      }
    );
  }

  const requestedStoryboard =
    String(input.dynamicFormValues.generation_mode || "").includes(
      "storyboard"
    ) ||
    String(input.dynamicFormValues.storyboard_layout_preset || "").trim() !==
      "";
  if (
    requestedStoryboard &&
    !/(equal|grid|panel|storyboard|same size|ช่อง|กริด|เท่ากัน|สตอรี่บอร์ด)/i.test(
      promptText
    )
  ) {
    addIssue(
      {
        id: "weak_storyboard_grid_contract",
        severity: "medium",
        title: isThai
          ? "พรอมต์ยังไม่ย้ำ storyboard grid/equal frame ชัดพอ"
          : "Storyboard grid contract is weak",
        recommendation: isThai
          ? "เพิ่ม rule ให้ทุก panel มีขนาดเท่ากัน ไม่มีกรอบ/ช่องว่างผิดรูป และตรง layout preset"
          : "Add rules requiring equal-sized panels, clean layout, and adherence to the selected preset.",
        affectedSection: "Storyboard layout",
      },
      {
        title: isThai
          ? "เพิ่ม storyboard grid consistency rule"
          : "Add storyboard grid consistency rule",
        reason: isThai
          ? "ลดปัญหาภาพออกมาเป็น collage/mosaic แทน storyboard ที่ควบคุมได้"
          : "Reduces collage/mosaic outputs when a controlled storyboard is requested.",
        targetFile,
        targetSection: "Storyboard format rules",
        risk: "low",
      }
    );
  }

  if (promptText.length > 0 && promptText.length < 600) {
    addIssue(
      {
        id: "prompt_too_short_for_reference_storyboard",
        severity: "medium",
        title: isThai
          ? "พรอมต์สั้นเกินไปสำหรับงาน reference storyboard"
          : "Prompt is short for a reference storyboard task",
        evidence: `${promptText.length} chars`,
        recommendation: isThai
          ? "เพิ่ม minimum completeness checklist ก่อน output เช่น subject, reference locks, scene beats, negative constraints"
          : "Add a minimum completeness checklist before output: subject, reference locks, scene beats, and negative constraints.",
        affectedSection: "Final output QA",
      },
      {
        title: isThai
          ? "เพิ่ม completeness checklist ก่อนส่ง prompt"
          : "Add final completeness checklist",
        reason: isThai
          ? "ช่วยให้ Auto Prompt มีรายละเอียดพอสำหรับ image model"
          : "Ensures Auto Prompt has enough detail for downstream image generation.",
        targetFile,
        targetSection: "Final QA loop",
        risk: "low",
      }
    );
  }

  if (issues.length === 0) {
    return null;
  }

  const score = Math.max(
    0,
    100 -
      issues.reduce((sum, issue) => {
        if (issue.severity === "high") return sum + 18;
        if (issue.severity === "medium") return sum + 10;
        return sum + 4;
      }, 0)
  );

  return {
    trigger: "prompt_qa",
    score,
    issues,
    proposedChanges,
  };
}

