function getSeparateVoiceFallbackFields(model: any): ModelInputField[] {
  if (!model) return [];
  if (hasCandidateIdContaining(model, "gemini-2.5")) {
    return buildGemini25TtsFallbackFields();
  }
  if (hasCandidateIdContaining(model, "gemini-3.1-flash-tts")) {
    return buildFalGemini31TtsFallbackFields();
  }
  if (hasCandidateIdContaining(model, "qwen3-tts")) {
    return buildQwen3TtsFallbackFields();
  }
  return [];
}

function mergeModelFieldOptions(
  currentOptions: unknown,
  requiredOptions: Array<{ value: string; label: string }>,
  options: {
    preferRequiredLabels?: boolean;
    prioritizeRequiredOptions?: boolean;
  } = {}
): Array<{ value: string; label: string }> {
  const byValue = new Map<string, { value: string; label: string }>();
  if (Array.isArray(currentOptions)) {
    for (const option of currentOptions) {
      if (!option || typeof option !== "object") continue;
      const record = option as Record<string, unknown>;
      const value = String(record.value ?? "").trim();
      if (!value) continue;
      byValue.set(value, {
        value,
        label: String(record.label ?? value).trim() || value,
      });
    }
  }

  for (const option of requiredOptions) {
    const existing = byValue.get(option.value);
    if (
      !existing ||
      options.preferRequiredLabels ||
      existing.label === option.value
    ) {
      byValue.set(option.value, option);
    }
  }

  if (options.prioritizeRequiredOptions) {
    const prioritized = new Map<string, { value: string; label: string }>();
    for (const option of requiredOptions) {
      const merged = byValue.get(option.value) ?? option;
      prioritized.set(option.value, merged);
    }
    for (const option of byValue.values()) {
      if (!prioritized.has(option.value)) {
        prioritized.set(option.value, option);
      }
    }
    return Array.from(prioritized.values());
  }

  return Array.from(byValue.values());
}

function normalizeModelInputFieldsForStudio(
  model: any,
  rawFields: unknown
): unknown[] {
  if (!Array.isArray(rawFields)) {
    return [];
  }
  const isGemini25Tts =
    hasCandidateIdContaining(model, "gemini-2.5") &&
    hasCandidateIdContaining(model, "text-to-speech");
  const isGemini31Tts = hasCandidateIdContaining(model, "gemini-3.1-flash-tts");

  return rawFields.map(field => {
    if (!field || typeof field !== "object" || Array.isArray(field)) {
      return field;
    }
    const record = { ...(field as Record<string, unknown>) };
    const normalizedKey = String(record.key ?? "")
      .trim()
      .toLowerCase();

    if (Array.isArray(record.itemFields)) {
      record.itemFields = normalizeModelInputFieldsForStudio(
        model,
        record.itemFields
      );
    }

    if (isGemini25Tts && normalizedKey === "language") {
      record.options = mergeModelFieldOptions(
        record.options,
        GEMINI_TTS_LANGUAGE_FIELD_OPTIONS,
        {
          prioritizeRequiredOptions: true,
        }
      );
    }
    if (isGemini31Tts && normalizedKey === "language_code") {
      record.options = mergeModelFieldOptions(
        record.options,
        GEMINI_31_TTS_LANGUAGE_CODE_FIELD_OPTIONS,
        {
          prioritizeRequiredOptions: true,
        }
      );
      record.searchable = true;
    }
    if ((isGemini25Tts || isGemini31Tts) && normalizedKey === "voice") {
      record.options = mergeModelFieldOptions(
        record.options,
        GEMINI_TTS_VOICE_FIELD_OPTIONS,
        {
          preferRequiredLabels: true,
        }
      );
      record.searchable = true;
    }

    return record;
  });
}

function withFallbackModelInputFields(
  model: any,
  fallbackFields: ModelInputField[]
): any {
  if (!model) {
    return model;
  }
  const config = parseMediaModelConfig(model.configJson);
  const rawFields =
    Array.isArray(config?.inputFields) && config.inputFields.length > 0
      ? config.inputFields
      : fallbackFields;
  if (!Array.isArray(rawFields) || rawFields.length === 0) {
    return model;
  }
  return {
    ...model,
    id: model.id ?? model.modelId,
    configJson: {
      ...(config ?? {}),
      inputFields: normalizeModelInputFieldsForStudio(model, rawFields),
    },
  };
}

function applyTtsLanguageDefaultsForPrompt(
  model: any,
  text: string,
  extraParams: Record<string, unknown>
): void {
  if (!containsThaiText(text)) {
    return;
  }
  if (
    hasCandidateIdContaining(model, "gemini-2.5") &&
    hasCandidateIdContaining(model, "text-to-speech")
  ) {
    const selectedLanguage = String(extraParams.language ?? "").trim();
    if (!selectedLanguage || selectedLanguage.startsWith("English")) {
      extraParams.language = "Thai (Thailand)";
    }
    return;
  }
  if (hasCandidateIdContaining(model, "gemini-3.1-flash-tts")) {
    const selectedLanguageCode = String(extraParams.language_code ?? "").trim();
    if (
      !selectedLanguageCode ||
      selectedLanguageCode === "__auto__" ||
      selectedLanguageCode.startsWith("English")
    ) {
      extraParams.language_code = "Thai (Thailand)";
    }
  }
}

function inferStoryboardClipDurationSeconds(
  promptText: string,
  fallbackSeconds = DEFAULT_STORYBOARD_CLIP_DURATION_SECONDS
): number {
  const match = promptText.match(/(\d+(?:\.\d+)?)\s*seconds?/i);
  const parsed = match ? Number.parseFloat(match[1] ?? "") : Number.NaN;
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallbackSeconds;
}

function buildVoiceoverText(params: {
  script: string;
  targetDurationSeconds: number;
  languageHint?: string;
}): string {
  return params.script.trim();
}

function buildVoiceoverStyleInstruction(params: {
  targetDurationSeconds: number;
  languageHint?: string;
}): string {
  const duration = Math.max(1, Math.round(params.targetDurationSeconds));
  const languageHint = params.languageHint?.trim();
  return [
    languageHint ? `${languageHint} news voiceover.` : "News voiceover.",
    `Finish in about ${duration} seconds.`,
    "Crisp, natural, professional, slightly brisk, no stretched syllables, no long dramatic pauses.",
  ].join(" ");
}

function buildMusicPromptFromPrompts(
  promptTexts: string[],
  targetDurationSeconds: number,
  fallbackPrompt: string
): string {
  const soundDesign = promptTexts
    .flatMap(promptText => promptText.split(/\r?\n/))
    .map(line => line.trim())
    .find(line => /^Sound Design\s*:/i.test(line));
  const duration = Math.max(1, Math.round(targetDurationSeconds));
  return [
    `${soundDesign || fallbackPrompt || "Subtle modern newsroom technology ambience"}.`,
    `Create a low-volume background music bed around ${duration} seconds, consistent across the whole video.`,
    "Clean, modern, restrained, no vocals, no spoken words, no sudden loud hits, leave room for voiceover.",
  ].join(" ");
}

function containsThaiText(text: string): boolean {
  return /[\u0E00-\u0E7F]/.test(text);
}

function estimateVoiceoverDurationSeconds(text: string): number {
  const normalized = text.replace(/\s+/g, " ").trim();
  if (!normalized) return 8;

  const thaiCharacters = (normalized.match(/[\u0E00-\u0E7F]/g) || []).length;
  const latinWords = (
    normalized.match(/[A-Za-z0-9]+(?:[-'][A-Za-z0-9]+)?/g) || []
  ).length;
  const nonThaiCharacters = Math.max(0, normalized.length - thaiCharacters);
  const thaiSeconds = thaiCharacters > 0 ? thaiCharacters / 11 : 0;
  const englishSeconds = latinWords > 0 ? latinWords / 2.45 : 0;
  const mixedFallbackSeconds =
    nonThaiCharacters > 0 && latinWords === 0 ? nonThaiCharacters / 14 : 0;

  return Math.max(
    4,
    Math.ceil(thaiSeconds + englishSeconds + mixedFallbackSeconds)
  );
}

function formatMediaDuration(seconds: number | null | undefined): string {
  if (!Number.isFinite(seconds ?? Number.NaN) || !seconds || seconds <= 0) {
    return "";
  }
  if (seconds < 60) {
    return `${seconds.toFixed(seconds >= 10 ? 0 : 1)}s`;
  }
  const minutes = Math.floor(seconds / 60);
  const remaining = Math.round(seconds % 60);
  return `${minutes}:${String(remaining).padStart(2, "0")}`;
}

async function probeMediaDurationSeconds(
  url: string,
  fallbackSeconds: number,
  mediaKind: "audio" | "video" = "audio"
): Promise<number> {
  if (typeof window === "undefined") return fallbackSeconds;
  return new Promise(resolve => {
    const media = document.createElement(mediaKind) as HTMLMediaElement;
    let settled = false;
    const finish = (value: number) => {
      if (settled) return;
      settled = true;
      media.removeAttribute("src");
      media.load();
      resolve(Number.isFinite(value) && value > 0 ? value : fallbackSeconds);
    };
    const timeout = window.setTimeout(() => finish(fallbackSeconds), 8000);
    media.preload = "metadata";
    media.onloadedmetadata = () => {
      window.clearTimeout(timeout);
      finish(media.duration);
    };
    media.onerror = () => {
      window.clearTimeout(timeout);
      finish(fallbackSeconds);
    };
    media.src = url;
  });
}

function normalizeModelFieldOptions(raw: unknown): SearchableFieldOption[] {
  if (!Array.isArray(raw)) return [];
  const options: SearchableFieldOption[] = [];
  for (const item of raw) {
    if (typeof item === "string") {
      const value = item.trim();
      if (!value) continue;
      options.push({ value, label: value });
      continue;
    }
    if (!item || typeof item !== "object") continue;
    const record = item as Record<string, unknown>;
    const valueRaw = record.value;
    const labelRaw = record.label;
    const previewUrlRaw = record.previewUrl;
    const value = typeof valueRaw === "string" ? valueRaw.trim() : "";
    const label = typeof labelRaw === "string" ? labelRaw.trim() : value;
    const previewUrl =
      typeof previewUrlRaw === "string" ? previewUrlRaw.trim() : "";
    if (!value) continue;
    options.push({
      value,
      label: label || value,
      ...(previewUrl ? { previewUrl } : {}),
    });
  }
  return options;
}

function getStoredOptionLabelKey(fieldKey: string): string {
  return `${fieldKey}__label`;
}

function readStoredOptionLabel(
  values: Record<string, unknown>,
  fieldKey: string,
  currentValue: string
): string {
  if (!currentValue) {
    return "";
  }
  const label = values[getStoredOptionLabelKey(fieldKey)];
  return typeof label === "string" ? label.trim() : "";
}

function hasProviderApiOptionsSource(
  field: Record<string, any> | null | undefined
): boolean {
  if (!field || typeof field !== "object") return false;
  const source = field.optionsSource;
  if (!source || typeof source !== "object") return false;
  const sourceType = String(
    (source as Record<string, unknown>).type || ""
  ).toLowerCase();
  return sourceType === "provider_api" || sourceType === "public_api";
}

function isSearchableModelField(
  field: Record<string, any> | null | undefined
): boolean {
  if (!field || typeof field !== "object") return false;
  if (field.searchable === true) return true;
  return hasProviderApiOptionsSource(field);
}

function isVoiceSelectionField(
  field: Record<string, any> | null | undefined
): boolean {
  if (!field || typeof field !== "object") return false;
  const source = field.optionsSource;
  if (source && typeof source === "object") {
    const sourceRecord = source as Record<string, unknown>;
    const valueField = String(sourceRecord.valueField ?? "")
      .trim()
      .toLowerCase();
    const previewField = String(sourceRecord.previewField ?? "")
      .trim()
      .toLowerCase();
    if (valueField === "voice_id" || previewField === "preview_url") {
      return true;
    }
  }
  const normalizedKey = String(field.key ?? "")
    .trim()
    .toLowerCase()
    .replace(/[_\-\s]/g, "");
  return (
    normalizedKey === "voice" ||
    normalizedKey === "voiceid" ||
    /^voiceid\d+$/.test(normalizedKey)
  );
}

function isUvoiceVoiceSelectionField(
  providerName: unknown,
  field: Record<string, any> | null | undefined
): boolean {
  return (
    String(providerName ?? "")
      .trim()
      .toLowerCase() === "uvoice" && isVoiceSelectionField(field)
  );
}

function getModelInputPreferenceStorageKey(
  mediaType: MediaType,
  modelId: string
): string {
  return `${MODEL_INPUT_PREF_STORAGE_PREFIX}:${mediaType}:${encodeURIComponent(modelId)}`;
}

function isPersistableModelInputField(
  field: Record<string, any> | null | undefined
): boolean {
  if (!field || typeof field !== "object") return false;
  const key = String(field.key ?? "").trim();
  if (!key || inferModelInputSyncTarget(field)) return false;
  if (isVoiceSelectionField(field)) return true;
  const type = String(field.type ?? "")
    .trim()
    .toLowerCase();
  return (
    type === "select" ||
    type === "boolean" ||
    type === "checkbox" ||
    type === "number"
  );
}

function sanitizePersistedModelInputValue(
  field: Record<string, any>,
  value: unknown
): unknown {
  if (
    isVoiceSelectionField(field) &&
    value === DEPRECATED_ELEVENLABS_DEFAULT_VOICE_ID
  ) {
    return undefined;
  }
  if (Array.isArray(value) || (value && typeof value === "object")) {
    return undefined;
  }
  return value;
}

function readPersistedModelInputPreferences(
  mediaType: MediaType,
  modelId: string,
  fields: Record<string, any>[]
): Record<string, any> {
  if (typeof window === "undefined") return {};
  try {
    const raw = window.localStorage.getItem(
      getModelInputPreferenceStorageKey(mediaType, modelId)
    );
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed))
      return {};

    const fieldMap = new Map(
      fields.map(field => [String(field.key ?? ""), field])
    );
    const values: Record<string, any> = {};
    for (const [key, value] of Object.entries(
      parsed as Record<string, unknown>
    )) {
      const sourceKey = key.endsWith("__label")
        ? key.slice(0, -"__label".length)
        : key;
      const field = fieldMap.get(sourceKey);
      if (!field || !isPersistableModelInputField(field)) continue;
      if (key.endsWith("__label")) {
        if (typeof value === "string" && value.trim())
          values[key] = value.trim();
        continue;
      }
      const sanitizedValue = sanitizePersistedModelInputValue(field, value);
      if (sanitizedValue !== undefined) values[key] = sanitizedValue;
    }
    return values;
  } catch {
    return {};
  }
}

function pickPersistableModelInputPreferences(
  fields: Record<string, any>[],
  values: Record<string, any>
): Record<string, any> {
  const preferences: Record<string, any> = {};
  for (const field of fields) {
    if (!isPersistableModelInputField(field)) continue;
    const key = String(field.key ?? "").trim();
    const sanitizedValue = sanitizePersistedModelInputValue(field, values[key]);
    if (sanitizedValue === undefined || sanitizedValue === "") continue;
    if (
      field.default !== undefined &&
      field.default !== null &&
      String(sanitizedValue) === String(field.default)
    ) {
      continue;
    }
    preferences[key] = sanitizedValue;

    const labelKey = getStoredOptionLabelKey(key);
    const label = values[labelKey];
    if (typeof label === "string" && label.trim()) {
      preferences[labelKey] = label.trim();
    }
  }
  return preferences;
}

function hasAnyPersistableModelInputValue(
  fields: Record<string, any>[],
  values: Record<string, any>
): boolean {
  return fields.some(field => {
    if (!isPersistableModelInputField(field)) return false;
    const key = String(field.key ?? "").trim();
    return key ? Object.prototype.hasOwnProperty.call(values, key) : false;
  });
}

function getDuplicateGeminiSpeakerIds(
  extraParams: Record<string, unknown> | undefined
): string[] {
  const speakers = extraParams?.speakers;
  if (!Array.isArray(speakers)) {
    return [];
  }

  const seen = new Set<string>();
  const duplicates = new Set<string>();

  for (const speaker of speakers) {
    if (!speaker || typeof speaker !== "object" || Array.isArray(speaker)) {
      continue;
    }

    const speakerIdValue = (speaker as Record<string, unknown>).speaker_id;
    const speakerId =
      typeof speakerIdValue === "string" ? speakerIdValue.trim() : "";
    if (!speakerId) {
      continue;
    }

    if (seen.has(speakerId)) {
      duplicates.add(speakerId);
    } else {
      seen.add(speakerId);
    }
  }

  return Array.from(duplicates);
}

function getMediaStudioModelInputValidationErrors(params: {
  modelId?: string | null;
  fields: ModelInputField[];
  extraParams: Record<string, unknown> | undefined;
  prompt: string;
  aspectRatio: string;
  referenceImageUrls: string[];
  referenceVideoUrls: string[];
}): string[] {
  const errors: string[] = [];
  const missingRequiredFields = getMissingRequiredModelFields(params.fields, {
    extraParams: params.extraParams,
    prompt: params.prompt,
    aspectRatio: params.aspectRatio,
    referenceImageUrls: params.referenceImageUrls,
    referenceVideoUrls: params.referenceVideoUrls,
  });
  if (missingRequiredFields.length > 0) {
    errors.push(
      `Please fill required model inputs: ${missingRequiredFields.join(", ")}`
    );
  }

  if (params.modelId === GEMINI_3_1_FLASH_TTS_MODEL_ID) {
    const duplicateSpeakerIds = getDuplicateGeminiSpeakerIds(
      params.extraParams
    );
    if (duplicateSpeakerIds.length > 0) {
      errors.push(
        `Speaker IDs must be unique: ${duplicateSpeakerIds.join(", ")}`
      );
    }
  }

  return errors;
}

function inferModelInputSyncTarget(
  field: Record<string, any> | null | undefined
): string {
  return inferMediaStudioModelInputSyncTarget(field);
}

function getVeo31ProviderModelId(
  model: unknown,
  extraParams?: Record<string, unknown>
): string {
  const explicit = String(extraParams?.model ?? "").trim();
  if (explicit) {
    return explicit;
  }
  return getVeoProviderModelId(
    model as MediaStudioVeoModelLike | null | undefined
  );
}

function hasChangedRecordValues(
  base: Record<string, unknown>,
  patch: Record<string, unknown>
): boolean {
  return Object.entries(patch).some(([key, value]) => base[key] !== value);
}

function getVeo31InputValidationErrors(params: {
  model: unknown;
  extraParams: Record<string, unknown>;
  referenceImageUrls: string[];
  aspectRatio?: string;
}): string[] {
  const generationType = String(params.extraParams.generationType ?? "").trim();
  if (!generationType) {
    return [];
  }

  const providerModel = getVeo31ProviderModelId(
    params.model,
    params.extraParams
  );
  const imageCount = params.referenceImageUrls.length;
  const errors: string[] = [];

  if (
    generationType === "FIRST_AND_LAST_FRAMES_2_VIDEO" &&
    (imageCount < 1 || imageCount > 2)
  ) {
    errors.push(
      "Veo 3.1 First & Last Frames mode requires 1 or 2 reference images. Use @Image1 as the Start frame and @Image2 as the End frame when provided."
    );
  }

  if (generationType === "REFERENCE_2_VIDEO") {
    if (!isFastVeoProviderModelId(providerModel)) {
      errors.push(
        "Veo Reference to Video is available only with a Fast Veo model."
      );
    }
    if (imageCount < 1 || imageCount > 3) {
      errors.push(
        "Veo 3.1 Reference to Video requires 1 to 3 reference images."
      );
    }
    if (
      String(params.aspectRatio ?? "")
        .trim()
        .toLowerCase() === "auto"
    ) {
      errors.push(
        "Veo 3.1 Reference to Video requires an explicit 16:9 or 9:16 aspect ratio."
      );
    }
  }

  return errors;
}

function modelSupportsFirstLastFrameGeneration(model: unknown): boolean {
  const field = getModelInputField(model as any, "generationType");
  return Boolean(
    field?.options?.some(
      option => String(option.value) === "FIRST_AND_LAST_FRAMES_2_VIDEO"
    )
  );
}

function pickDefaultSplitStoryboardVideoModelId(models: any[]): string {
  const exactVeo31 = models.find(
    model => String(model.modelId ?? model.id ?? "") === "veo-3-1"
  );
  if (exactVeo31?.modelId || exactVeo31?.id)
    return String(exactVeo31.modelId ?? exactVeo31.id);

  const firstLastModel = models.find(modelSupportsFirstLastFrameGeneration);
  if (firstLastModel?.modelId || firstLastModel?.id)
    return String(firstLastModel.modelId ?? firstLastModel.id);

  const veoModel = models.find(model =>
    isVeoProviderModelId(getVeoProviderModelId(model))
  );
  if (veoModel?.modelId || veoModel?.id)
    return String(veoModel.modelId ?? veoModel.id);

  return String(models[0]?.modelId ?? models[0]?.id ?? "");
}

const VEO_REFERENCE_IMAGE_ROLE_INSTRUCTION = [
  "Reference image mode: use the attached image(s) only as material, identity, style, product, object, animal, or scene references.",
  "Do not treat any attached image as a start frame, end frame, frozen opening frame, or exact first/last frame unless generationType is FIRST_AND_LAST_FRAMES_2_VIDEO.",
].join(" ");

function prepareVeoPromptForGenerationType(
  promptText: string,
  generationType: unknown
): string {
  if (String(generationType ?? "").trim() !== "REFERENCE_2_VIDEO") {
    return promptText;
  }

  if (
    /Reference image mode:/i.test(promptText) ||
    /not .*start frame/i.test(promptText)
  ) {
    return promptText;
  }

  return `${VEO_REFERENCE_IMAGE_ROLE_INSTRUCTION}\n${promptText}`.trim();
}

function shouldSendReferenceImagesForMediaGeneration(
  model: unknown,
  extraParams: Record<string, unknown>
): boolean {
  const providerModel = getVeo31ProviderModelId(model, extraParams);
  if (!isVeoProviderModelId(providerModel)) {
    return true;
  }

  const generationType = String(extraParams.generationType ?? "").trim();
  return generationType !== "TEXT_2_VIDEO";
}

function removeReferenceImageSyncedParams(
  extraParams: Record<string, unknown>,
  inputFields: unknown
): void {
  if (!Array.isArray(inputFields)) {
    delete extraParams.imageUrls;
    delete extraParams.image_urls;
    delete extraParams.referenceImages;
    delete extraParams.reference_image_urls;
    return;
  }

  for (const field of inputFields) {
    if (
      inferModelInputSyncTarget(field as Record<string, unknown>) ===
      "reference_images"
    ) {
      const key = String((field as Record<string, unknown>).key ?? "").trim();
      if (key) {
        delete extraParams[key];
      }
    }
  }
}

function countMultiVideoPromptBlocks(rawText: string): number {
  const parsed = parseMediaStudioPromptPackage(rawText);
  const promptText = parsed.promptText || rawText.trim();
  return splitMultiVideoPromptOutput(promptText).prompts.length;
}

