function sleepMs(ms: number): Promise<void> {
  return new Promise(resolve => {
    window.setTimeout(resolve, ms);
  });
}

function normalizeQueueStatus(
  status: string | undefined | null
): QueueGenerationTask["status"] {
  switch ((status || "").toLowerCase()) {
    case "queued":
      return "queued";
    case "pending":
      return "pending";
    case "processing":
      return "processing";
    case "completed":
      return "completed";
    case "failed":
      return "failed";
    case "cancelled":
      return "cancelled";
    case "generating":
      return "processing";
    case "error":
      return "failed";
    default:
      return "pending";
  }
}

function normalizeStoredProductionStoryConceptWizard(
  value: unknown
): ProductionStoryConceptWizardState | null {
  if (!value || typeof value !== "object") return null;
  const record = value as Partial<ProductionStoryConceptWizardState>;
  if (!Array.isArray(record.options) || record.options.length === 0)
    return null;
  return {
    status: record.status === "idle" ? "idle" : "options_ready",
    options: record.options
      .filter((option): option is ProductionStoryConceptOption =>
        Boolean(
          option &&
          typeof option === "object" &&
          typeof (option as ProductionStoryConceptOption).id === "string"
        )
      )
      .map(option => sanitizeProductionStoryConceptOption(option, option)),
    selectedId:
      typeof record.selectedId === "string"
        ? record.selectedId
        : record.selectedId === null
          ? null
          : (record.options[0]?.id ?? null),
    contextSummary:
      typeof record.contextSummary === "string"
        ? record.contextSummary
        : undefined,
    generatedAt:
      typeof record.generatedAt === "string" ? record.generatedAt : undefined,
    generationSeed:
      typeof record.generationSeed === "string"
        ? record.generationSeed
        : undefined,
    source: record.source,
  };
}

function collectStringValues(
  value: unknown,
  output: string[],
  depth = 0
): void {
  if (depth > 5 || value == null) return;
  if (typeof value === "string") {
    output.push(value);
    return;
  }
  if (Array.isArray(value)) {
    value.forEach(item => collectStringValues(item, output, depth + 1));
    return;
  }
  if (typeof value === "object") {
    Object.values(value as Record<string, unknown>).forEach(item =>
      collectStringValues(item, output, depth + 1)
    );
  }
}

function getMediaCapacityRetryDelayMsFromMessage(
  value: unknown
): number | null {
  const messages: string[] = [];
  collectStringValues(value, messages);
  const text = messages.join("\n").replace(/\s+/g, " ").trim();
  if (!text) return null;
  if (
    !/points used by apiKey has exceeded the hourly limit|hourly limit|rate limit exceeded for media generation|too many requests|quota/i.test(
      text
    )
  ) {
    return null;
  }
  const secondsMatch =
    text.match(/try again in\s+(\d+(?:\.\d+)?)\s*seconds?/i) ||
    text.match(/retry after\s+(\d+(?:\.\d+)?)\s*seconds?/i);
  if (!secondsMatch) {
    return 5 * 60 * 1000;
  }
  return Math.max(
    15 * 1000,
    Math.min(60 * 60 * 1000, Math.ceil(Number(secondsMatch[1]) * 1000 + 5000))
  );
}

function getQueueProgress(status: QueueGenerationTask["status"]): number {
  switch (status) {
    case "queued":
      return 10;
    case "pending":
      return 25;
    case "processing":
      return 60;
    case "completed":
      return 100;
    case "failed":
    case "cancelled":
      return 100;
    default:
      return 0;
  }
}

