  useEffect(() => {
    window.localStorage.setItem(
      MEDIA_STUDIO_RIGHT_PANEL_COLLAPSED_KEY,
      String(isRightPanelCollapsed)
    );
  }, [isRightPanelCollapsed]);

  useEffect(() => {
    const handleWindowResize = () => {
      const previous = floatingPreviewViewportRef.current;
      const next = {
        width: window.innerWidth,
        height: window.innerHeight,
      };
      floatingPreviewViewportRef.current = next;

      if (
        isFloatingPreviewMaximized ||
        previous.width <= 0 ||
        previous.height <= 0
      ) {
        setFloatingPreviewFrame(frame => clampFloatingPreviewFrame(frame));
        return;
      }

      const widthRatio = next.width / previous.width;
      const heightRatio = next.height / previous.height;
      setFloatingPreviewFrame(frame =>
        clampFloatingPreviewFrame({
          x: Math.round(frame.x * widthRatio),
          y: Math.round(frame.y * heightRatio),
          width: Math.round(frame.width * widthRatio),
          height: Math.round(frame.height * heightRatio),
        })
      );
    };

    window.addEventListener("resize", handleWindowResize);
    return () => window.removeEventListener("resize", handleWindowResize);
  }, [isFloatingPreviewMaximized]);

  useEffect(() => {
    const handleRightPanelShortcut = (event: KeyboardEvent) => {
      if (event.key !== "]" || event.metaKey || event.ctrlKey || event.altKey)
        return;
      const target = event.target as HTMLElement | null;
      const tagName = target?.tagName?.toLowerCase();
      if (
        target?.isContentEditable ||
        tagName === "input" ||
        tagName === "textarea" ||
        tagName === "select"
      ) {
        return;
      }
      event.preventDefault();
      setIsRightPanelCollapsed(value => !value);
    };

    window.addEventListener("keydown", handleRightPanelShortcut);
    return () =>
      window.removeEventListener("keydown", handleRightPanelShortcut);
  }, []);

  const openPreview = useCallback(
    (
      url: string | null | undefined,
      contextTab: MediaType | null = activeTab,
      marketplaceProduct?: MarketplaceProductReferenceContext | null,
      options?: { mode?: FloatingPreviewDisplayMode }
    ) => {
      if (!url) return;
      setExpiredUrls(prev => {
        if (!prev.has(url)) return prev;
        const next = new Set(prev);
        next.delete(url);
        return next;
      });
      setPreviewUrl(url);
      setPreviewMarketplaceContext(marketplaceProduct ?? null);
      setPreviewContextTab(contextTab);
      setFloatingPreviewMode(options?.mode ?? "media");
      setIsFloatingPreviewOpen(true);
    },
    [activeTab]
  );

  const beginFloatingPreviewDrag = useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      if (isFloatingPreviewMaximized) {
        return;
      }
      event.preventDefault();
      const startX = event.clientX;
      const startY = event.clientY;
      const startFrame = floatingPreviewFrame;

      const handleMove = (moveEvent: MouseEvent) => {
        setFloatingPreviewFrame(
          clampFloatingPreviewFrame({
            ...startFrame,
            x: startFrame.x + moveEvent.clientX - startX,
            y: startFrame.y + moveEvent.clientY - startY,
          })
        );
      };

      const handleUp = () => {
        window.removeEventListener("mousemove", handleMove);
        window.removeEventListener("mouseup", handleUp);
      };

      window.addEventListener("mousemove", handleMove);
      window.addEventListener("mouseup", handleUp);
    },
    [floatingPreviewFrame, isFloatingPreviewMaximized]
  );

  const beginFloatingPreviewResize = useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      if (isFloatingPreviewMaximized) {
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      const startX = event.clientX;
      const startY = event.clientY;
      const startFrame = floatingPreviewFrame;

      const handleMove = (moveEvent: MouseEvent) => {
        setFloatingPreviewFrame(
          clampFloatingPreviewFrame({
            ...startFrame,
            width: startFrame.width + moveEvent.clientX - startX,
            height: startFrame.height + moveEvent.clientY - startY,
          })
        );
      };

      const handleUp = () => {
        window.removeEventListener("mousemove", handleMove);
        window.removeEventListener("mouseup", handleUp);
      };

      window.addEventListener("mousemove", handleMove);
      window.addEventListener("mouseup", handleUp);
    },
    [floatingPreviewFrame, isFloatingPreviewMaximized]
  );

